  const [batchResults, setBatchResults] = useState<ReturnType<typeof processBatchCsv> | null>(null);
  const [batchFileName, setBatchFileName] = useState<string>('');

  // Diagnostics
  const currentDiagnosis = diagnoseMachine(inputState, threshold);

  const applyPreset = (presetName: string) => {
    setPredictionHistoryCount(prev => prev + 1);
    if (presetName === 'nominal') {
      setInputState({ type: 'M', airTemp: 298.1, procTemp: 308.6, rotSpeed: 1551, torque: 42.8, toolWear: 15 });
    } else if (presetName === 'wear') {
      setInputState({ type: 'L', airTemp: 300.5, procTemp: 310.2, rotSpeed: 1420, torque: 49.0, toolWear: 225 });
    } else if (presetName === 'torque') {
      setInputState({ type: 'H', airTemp: 301.2, procTemp: 310.8, rotSpeed: 1260, torque: 72.0, toolWear: 110 });
    } else if (presetName === 'thermal') {
      setInputState({ type: 'L', airTemp: 304.5, procTemp: 313.1, rotSpeed: 1360, torque: 58.0, toolWear: 185 });
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setBatchFileName(file.name);
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        const res = processBatchCsv(text, threshold);
        setBatchResults(res);
        setPredictionHistoryCount(prev => prev + res.summary.valid);
      }
    };
    reader.readAsText(file);
  };

